import json,hashlib,datetime,subprocess
from pathlib import Path
p=Path(__file__).resolve().parent;root=p.parents[2];folder=p/'go-source-graph-controls-v1';folder.mkdir();base=json.loads(next((p/'go-stdlib-type-relations-v1').glob('*.request.json')).read_text());sha=lambda b:hashlib.sha256(b).hexdigest()
def pkg(name,src):return {'package_path':name,'files':[{'path':'owned.go','source':src,'sha256':sha(src.encode())}]}
api=pkg('research.example/api','package api\ntype Result = int\ntype Worker interface { Work() Result }\n')
client=pkg('research.example/client','package client\nimport "research.example/api"\ntype Concrete struct{}\nfunc(Concrete) Work() api.Result {return 1}\nvar _ api.Worker = Concrete{}\nfunc Dispatch(w api.Worker) api.Result{return w.Work()}\n')
method=pkg('research.example/client',client['files'][0]['source']+'var Method = api.Worker.Work\n')
cases=[{'id':'valid-alias-interface','packages':[api,client],'expected':'TYPECHECKED_FROZEN_SOURCE_GRAPH'}, {'id':'interface-not-runtime-concrete','packages':[api,method],'expected':'TYPECHECKED_FROZEN_SOURCE_GRAPH'}, {'id':'missing-dependency','packages':[client],'expected':'INCONCLUSIVE_TYPE_OR_IMPORT_ERRORS'}, {'id':'dependency-type-error','packages':[pkg(api['package_path'],api['files'][0]['source']+'const Broken int="bad"\n'),client],'expected':'INCONCLUSIVE_TYPE_OR_IMPORT_ERRORS'}, {'id':'source-cycle','packages':[pkg(api['package_path'],'package api\nimport "research.example/client"\ntype Result = int\ntype Worker interface {Work() Result}\nvar _ client.Concrete\n'),client],'expected':'INCONCLUSIVE_TYPE_OR_IMPORT_ERRORS'}, {'id':'standard-shadow','packages':[pkg('context','package context\nconst Local=1\n')],'expected':'REFUSED'}, {'id':'unreferenced-type-error','packages':[api,client,pkg('research.example/unused','package unused\nconst Broken int="bad"\n')],'expected':'INCONCLUSIVE_TYPE_OR_IMPORT_ERRORS'}, {'id':'source-hash-mismatch','packages':[json.loads(json.dumps(api)),client],'expected':'REFUSED'}, {'id':'duplicate-json-key','packages':[api,client],'expected':'REFUSED'}];cases[-2]['packages'][0]['files'][0]['sha256']='0'*64
binary=p/'offline-go-type-observer-v3/observer';protocol={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'binary_sha256':sha(binary.read_bytes()),'cases':cases,'role':'Owned development controls, not independent language/model benchmark','standard_manifest_sha256':sha((p/'go-stdlib-export-closure-v1/manifest-v2.json').read_bytes())};(folder/'protocol.json').open('x').write(json.dumps(protocol,indent=2)+'\n');records=[]
for c in cases:
 q={'packages':c['packages'],'export_root':str(root),'standard_exports':base['standard_exports']};raw=json.dumps(q).encode()
 if c['id']=='duplicate-json-key':raw=b'{"packages":[],'+raw[1:]
 (folder/(c['id']+'.request.json')).open('xb').write(raw);r=subprocess.run([str(binary)],input=raw,capture_output=True,timeout=25);(folder/(c['id']+'.stdout.json')).open('xb').write(r.stdout);(folder/(c['id']+'.stderr.txt')).open('xb').write(r.stderr);packet=json.loads(r.stdout);matched=packet['status']==c['expected'];assert r.returncode==0
 if packet['status']!='TYPECHECKED_FROZEN_SOURCE_GRAPH':assert not packet['relations'] and not packet['declarations'] and not packet['partial_type_info_admitted']
 if c['id']=='interface-not-runtime-concrete':assert any(x['kind']=='MethodVal' and 'api.Worker' in x['receiver'] for x in packet['relations']);assert any(x['kind']=='MethodExpr' for x in packet['relations'])
 records.append({'id':c['id'],'expected':c['expected'],'matched':matched,'packet':packet})
with (folder/'results.json').open('x') as f:json.dump({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'records':records,'mechanism_expectations_matched':sum(r['matched'] for r in records),'total':len(records),'no_independent_accuracy_inferred':True,'target_source_executed':False,'model_calls':0},f,indent=2);f.write('\n')
print(json.dumps({'cases':len(records),'matched':sum(r['matched'] for r in records),'statuses':[(r['id'],r['packet']['status']) for r in records]}));assert all(r['matched'] for r in records)
